add('R04-REG-APPLIED-12','FCCの胞質量をSI体積で割り密度を求める。',['7.9×10^3kg/m3','1.2×10^4kg/m3','1.5×10^4kg/m3','1.9×10^4kg/m3','2.3×10^4kg/m3'],['計算密度に達しない。','計算密度より小さい。','計算密度より小さい。','胞原子数4とa=4.1×10^-10mから約1.91×10^4。','計算密度より大きい。'],4,'FCC慣用胞の原子数は8×1/8+6×1/2=4。胞質量は4×0.197/(6.0×10^23)kg、体積は(4.1×10^-10)^3m3。ρ=1.9056×10^4kg/m3なので4。197g/molをkg/molへ直す。H26と同じ方法だが構造・単位・数値が異なる。','atomic_crystal_density','density',['openstax_crystals'],conditions={'構造':'FCC','格子定数':'0.41nm','原子量':'197','指定NA':'6.0×10^23mol^-1','求める単位':'kg/m3'},calc=True)
add('H26-REG-APPLIED-11','分子極性と水素結合の供与・受容を判断する。',['極性の強い水素化合物に多い','CH4は強極性で水素結合','水の沸点はH2Sより高い','HFは高い電気陰性度に関係','異種分子間にも水素結合'],['典型的なN/O/Fに結合したH等を入口とする。','正四面体CH4の結合双極子は相殺し、強極性という前提が誤り。','水の分子間水素結合が高い沸点を説明する。','HFの分極した結合と電子対による相互作用。','供与体と受容体が違う分子でも成立する。'],2,'CH4は対称な正四面体で永久双極子がなく、極性が強いため水素結合を生じるという2が不適切。水・HFの典型的水素結合や異種分子間の供与体/受容体を区別する。水素を含めば全て同等の水素結合が生じるという推論はできない。','atomic_intermolecular','interactions',['atomic_nonbond'])
add('H27-REG-APPLIED-09','NaClの配位数と硬球近似の距離を区別する。',['単位格子は立方体','静電引力による結晶','最近接Clは4個','隣接Na/Clは全て接触','最近接Na-Naは√2(rNa+rCl)'],['慣用胞は立方。','陽陰イオンの静電相互作用。','Naの周囲のClは上下左右前後の6個。','イオン半径による硬球近似の記述で、電子雲の厳密境界ではない。','Na-Cl距離a/2=rNa+rClとNa-Na=a/√2から導く近似式。'],3,'NaCl型は最近接異種イオンの配位数6で、4とする3が不適切。陽陰それぞれのFCC副格子がずれて重なる。硬球接触を置くとa/2=rNa+rCl、同種最近接a/√2=√2(rNa+rCl)。格子の幾何と、半径の和を実距離とするモデル仮定を分ける。','atomic_ionic_structures','ionic',['openstax_crystals'],ambiguity='全隣接イオンが接するという記述はイオン半径の硬球近似。半径の定義・実結晶条件は原典で未指定。')
add('H27-REG-APPLIED-11','飽和溶液質量を分母にした溶解度から析出量を求める。',['15.1g','24.0g','28.2g','37.1g','59.0g'],['冷却後の溶存量で析出量ではない。','冷却前の水量を100gと誤認。','52.2−24.0は溶液量が変わることを無視。','水47.8gを保持し溶存15.0947gを差し引く。','初期溶質52.2gより大きく質量保存に反する。'],4,'原典の定義は100gの飽和水溶液中の溶質量。60℃の100gには溶質52.2g、水47.8gがある。蒸発を無視し20℃で溶質/水=24/76とすると残る溶質は47.8×24/76=15.0947g。析出52.2−15.0947=37.1053gで4。100g水当たりという通常の別定義へ読み替えない。','atomic_solubility_mass','solubility',ambiguity='水の蒸発なし・析出結晶への水の取込みなしを置く物質収支。原典の分母は飽和溶液。',conditions={'60℃溶質':'飽和溶液100g中52.2g','20℃溶質':'飽和溶液100g中24.0g','水の初期量':'47.8g'},calc=True,discipline='chem_physical')
add('H28-REG-APPLIED-10','原子番号と質量数から同位体を定義する。',['硫黄の異なる単体','原子番号同一・質量数不同','陽子と中性子の和が同じ','周期表の同族','アルカン等の同族列'],['同素体の説明。','同じZ、違う中性子数N、A=Z+Nが異なる。','同じAの同重体でZ同一とは限らない。','電子配置による化学的族の分類。','有機化合物の同族列で核種ではない。'],2,'同位体はZが等しくNが違う原子の組で、A=Z+Nは異なる。2。1は同素体、3は同重体、4は周期表の族、5は有機同族列。単体の結晶構造が違うことと核の中性子数が違うことを混同しない。','isotope_general','isotopes',['modern_mit_nuclear'])
